public func disconnect() async {
    DockLog.appServer.notice("app-server disconnect requested state=\(self.state.logDescription, privacy: .public) pending=\(self.pendingRequests.count, privacy: .public)")
    isExplicitlyDisconnected = true
    reconnectTask?.cancel()
    reconnectTask = nil
    receiveTask?.cancel()
    receiveTask = nil
    failAllPending(with: .disconnected("client disconnected"))
    await transport.disconnect()
    setState(.closed(reason: "client disconnected"))
    connectionStateContinuation.finish()
    notificationContinuation.finish()
    serverRequestContinuation.finish()
}

private func openTransport(mode: TransportOpenMode) async throws {
    DockLog.appServer.info("app-server transport open started mode=\(mode.logDescription, privacy: .public)")
    if mode == .initial {
        setState(.connecting)
    }

    do {
        try await transport.connect()
        startReceiveLoop()
        DockLog.appServer.info("app-server transport open finished mode=\(mode.logDescription, privacy: .public)")
    } catch {
        let wrapped = AppServerClientError.transport(error.localizedDescription)
        if mode == .initial {
            setState(.offline(reason: wrapped.localizedDescription))
        }
        DockLog.appServer.error("app-server transport open failed mode=\(mode.logDescription, privacy: .public) error=\(DockLog.errorSummary(wrapped), privacy: .public)")
        throw wrapped
    }
}

private func completeInitializeHandshake(
    params: InitializeParams,
    timeout: Duration
) async throws -> InitializeResponse {
    let response = try await initialize(params: params, timeout: timeout)
    try await sendNotification(method: AppServerMethods.initialized, allowsConnecting: true)
    serverInfo = response
    setState(.connected)
    return response
}

private func initialize(
    params: InitializeParams,
    timeout: Duration
) async throws -> InitializeResponse {
    let paramsValue = try JSONValue.encoded(params)
    let result = try await sendRequest(
        id: .string("initialize"),
        method: AppServerMethods.initialize,
        params: paramsValue,
        timeout: timeout,
        allowsConnecting: true,
        observabilityContext: nil
    )
    return try decodeResponse(result, as: InitializeResponse.self)
}

private func sendRequest(
    id: JSONRPCRequestID,
    method: String,
    params: JSONValue?,
    timeout: Duration,
    allowsConnecting: Bool,
    observabilityContext: AppServerRequestObservabilityContext?
) async throws -> JSONValue {
    try ensureCanSend(allowsConnecting: allowsConnecting)

    guard pendingRequests[id] == nil else {
        DockLog.appServer.error("app-server request duplicate method=\(method, privacy: .public) request_id=\(DockLog.publicID(id), privacy: .public)")
        throw AppServerClientError.duplicateRequestID(id)
    }

    if let observabilityContext {
        await observabilityContext.store?.start(observabilityContext)
    }
    let request = JSONRPCRequest(
        id: id,
        method: method,
        params: paramsWithTraceMetadata(params, context: observabilityContext)
    )
    let text = try JSONRPCMessage.request(request).jsonString()
    DockLog.appServer.info("app-server request started method=\(method, privacy: .public) request_id=\(DockLog.publicID(id), privacy: .public)")

    return try await withTaskCancellationHandler {
        try await withCheckedThrowingContinuation { continuation in
            let timeoutTask = Task { [weak self] in
                do {
                    try await Task.sleep(for: timeout)
                    await self?.finishPending(
                        id: id,
                        result: .failure(AppServerClientError.requestTimedOut(id))
                    )
                } catch {
                    return
                }
            }

            pendingRequests[id] = PendingRequest(
                method: method,
                startedAt: Date(),
                observabilityContext: observabilityContext,
                continuation: continuation,
                timeoutTask: timeoutTask
            )

            Task { [weak self] in
                do {
                    try await self?.sendRaw(text)
                } catch {
                    await self?.finishPending(
                        id: id,
                        result: .failure(AppServerClientError.transport(error.localizedDescription))
                    )
                    await self?.handleConnectedSendFailure(error.localizedDescription)
                }
            }
        }
    } onCancel: {
        Task { [weak self] in
            await self?.finishPending(
                id: id,
                result: .failure(AppServerClientError.requestCancelled(id))
            )
        }
    }
}

private func allocateRequestID() -> JSONRPCRequestID {
    let id = JSONRPCRequestID.integer(nextRequestNumber)
    nextRequestNumber += 1
    return id
}

private func paramsWithTraceMetadata(
    _ params: JSONValue?,
    context: AppServerRequestObservabilityContext?
) -> JSONValue? {
    guard let context else {
        return params
    }
    switch params {
    case .object(let object):
        var next = object
        next[ObservabilityContract.traceParamKey] = context.traceJSONValue
        return .object(next)
    case nil:
        return .object([ObservabilityContract.traceParamKey: context.traceJSONValue])
    case .array, .bool, .double, .integer, .null, .string:
        return params
    }
}

private func send(_ message: JSONRPCMessage) async throws {
    let text = try message.jsonString()
    try await sendRaw(text)
}

private func sendRaw(_ text: String) async throws {
    do {
        try await transport.send(text)
    } catch {
        throw AppServerClientError.transport(error.localizedDescription)
    }
}

private func startReceiveLoop() {
    receiveTask?.cancel()
    receiveTask = Task { [weak self, transport] in
        await self?.logReceiveLoopStarted()
        while !Task.isCancelled {
            do {
                guard let text = try await transport.receive() else {
                    await self?.handleTransportLoss("transport closed")
                    return
                }

                let message: JSONRPCMessage
                do {
                    message = try JSONRPCMessage.decode(from: text)
                } catch {
                    DockLog.appServer.error("app-server received malformed message error=\(DockLog.errorSummary(error), privacy: .public)")
                    await self?.failConnection(.malformedMessage(error.localizedDescription))
                    return
                }

                await self?.handleIncoming(message)
            } catch is CancellationError {
                await self?.logReceiveLoopEnded(reason: "cancelled")
                return
            } catch {
                await self?.handleTransportLoss(error.localizedDescription)
                return
            }
        }
    }
}

private func handleTransportLoss(_ reason: String) async {
    DockLog.appServer.warning("app-server transport lost reason=\(DockLog.redacted(reason), privacy: .public) reconnect_enabled=\((self.connectionPolicy.reconnect != nil), privacy: .public)")
    receiveTask = nil
    failAllPending(with: .disconnected(reason))
    await transport.disconnect()

    guard connectionPolicy.reconnect != nil,
          initializeParams != nil,
          !isExplicitlyDisconnected else {
        markOffline(reason)
        return
    }

    startReconnect(reason: reason)
}

private func startReconnect(reason: String) {
    guard reconnectTask == nil else {
        return
    }
    DockLog.appServer.warning("app-server reconnect loop scheduled reason=\(DockLog.redacted(reason), privacy: .public)")
    reconnectTask?.cancel()
    reconnectTask = Task { [weak self] in
        await self?.runReconnectLoop(reason: reason)
    }
}

private func runReconnectLoop(reason: String) async {
    guard let reconnect = connectionPolicy.reconnect,
          let params = initializeParams else {
        markOffline(reason)
        return
    }

    var lastErrorReason = reason
    for attempt in 1...reconnect.maxAttempts {
        guard !Task.isCancelled, !isExplicitlyDisconnected else {
            return
        }
        guard await waitForForegroundWorkIfNeeded() else {
            return
        }

        setState(.reconnecting(attempt: attempt, reason: lastErrorReason))
        DockLog.appServer.notice("app-server reconnect attempt started attempt=\(attempt, privacy: .public) max_attempts=\(reconnect.maxAttempts, privacy: .public)")

        do {
            try await Task.sleep(for: reconnect.delay(for: attempt))
        } catch {
            return
        }

            liveState = .stale(message(from: error))
            publishLoaded()
            DockLog.threadDetail.warning("thread detail rehydrate failed thread_id=\(DockLog.publicID(self.row.threadID), privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
        }

        recoveryTask = nil
    }

    private func queueDockRowRefresh(for marker: DockRowActivityMarker, force: Bool = false) {
        if !force, !marker.isNewer(than: lastCompletedDockRowRefreshMarker) {
            return
        }
        if let pending = pendingDockRowRefreshMarker,
           pending.isNewer(than: marker) || pending == marker {
            return
        }

        pendingDockRowRefreshMarker = marker
        DockLog.threadDetail.notice("thread detail dock row advanced thread_id=\(DockLog.publicID(self.row.threadID), privacy: .public)")
        startDockRowRefreshIfNeeded()
    }

    private func scheduleDockRowSettleRefresh(for marker: DockRowActivityMarker) {
        dockRowSettleRefreshTask?.cancel()
        let delay = dockRowSettleRefreshDelay
        dockRowSettleRefreshTask = Task { [weak self] in
            do {
                try await Task.sleep(for: delay)
            } catch {
                return
            }
            self?.queueDockRowSettleRefreshIfCurrent(marker)
        }
    }

    private func queueDockRowSettleRefreshIfCurrent(_ marker: DockRowActivityMarker) {
        guard !isClosing, marker == latestDockRowActivityMarker else {
            return
        }
        DockLog.threadDetail.notice("thread detail dock row settle refresh queued thread_id=\(DockLog.publicID(self.row.threadID), privacy: .public)")
        queueDockRowRefresh(for: marker, force: true)
    }

    private func startDockRowRefreshIfNeeded() {
        guard !isClosing,
              recoveryTask == nil,
              let marker = pendingDockRowRefreshMarker,
              case .loaded = state,
              liveState != .closed,
              let session else {
            return
        }

        pendingDockRowRefreshMarker = nil
        recoveryTask = Task { [weak self] in
            await self?.rehydrateAfterDockRowAdvance(session: session, marker: marker)
        }
    }

    private func rehydrateAfterDockRowAdvance(
        session: any ThreadDetailSession,
        marker: DockRowActivityMarker
    ) async {
        guard !isClosing, case .loaded = state else {
            recoveryTask = nil
            return
        }

        liveEventBuffer.begin()
        DockLog.threadDetail.notice("thread detail dock row refresh started thread_id=\(DockLog.publicID(self.row.threadID), privacy: .public)")

        do {
            let detailSnapshot = try await session.threadDetailResync(
                params: ThreadDetailParams(threadId: row.threadID),
                timeout: CodexDockConstants.AppServer.defaultRequestTimeout
            )
            try await replaceEvents(from: detailSnapshot, liveState: .live)
            await replayBufferedLiveEvents()
            DockLog.threadDetail.notice("thread detail dock row refresh finished thread_id=\(DockLog.publicID(self.row.threadID), privacy: .public) events=\(self.events.count, privacy: .public)")
        } catch {
            liveEventBuffer.discard()
            liveState = .stale(message(from: error))
            publishLoaded()
            DockLog.threadDetail.warning("thread detail dock row refresh failed thread_id=\(DockLog.publicID(self.row.threadID), privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
        }

        recoveryTask = nil
        if case .loaded = state, liveState == .live {
            lastCompletedDockRowRefreshMarker = marker
        }
        startDockRowRefreshIfNeeded()
    }

    private func markLiveSessionReconnecting(_ message: String) {
        guard !isClosing, case .loaded = state else {
            return
        }
        switch liveState {
        case .closed:
            return
        case .connecting, .reconnecting, .live, .stale:
            liveState = .reconnecting(message)
            DockLog.threadDetail.notice("thread detail reconnecting thread_id=\(DockLog.publicID(self.row.threadID), privacy: .public) reason=\(DockLog.redacted(message), privacy: .public)")
            publishLoaded()
        }
    }

    private func replaceEvents(
        from detailSnapshot: ThreadDetailSnapshotDTO,
        liveState: ThreadDetailLiveState
    ) async throws {
        let snapshot = try await dataEngine.replace(
            from: detailSnapshot,
            expectedThreadID: row.threadID,
            expectedSourceHostID: row.sourceHostID
        )
        applyDataSnapshot(snapshot)
        requestCardPresentation.prune(to: snapshot.events)
        self.liveState = liveState
        publishLoaded()
    }

    private func replayBufferedLiveEvents() async {
        while let bufferedEvents = liveEventBuffer.takeBatch() {
            for event in bufferedEvents {
                switch event {
                case .notification(let notification):
                    await apply(notification: notification)
                }
            }
        }
        liveEventBuffer.finishReplay()
    }

    private func handle(notification: JSONRPCNotification) async {
        if liveEventBuffer.isBuffering {
            liveEventBuffer.append(notification: notification)
            DockLog.threadDetail.debug("thread notification buffered during canonical load method=\(notification.method, privacy: .public) thread_id=\(DockLog.publicID(self.row.threadID), privacy: .public)")
            return
        }
        await apply(notification: notification)
    }

    private func apply(notification: JSONRPCNotification) async {
        guard notification.method == AppServerMethods.threadDetailUpdate else {
            return
        }

        do {
            let update = try notification.params?.decoded(as: ThreadDetailUpdateDTO.self)
            guard let update else {
                return
            }
            if update.kind == .resyncRequired {
                if let session {
                    await rehydrateAfterReconnect(session: session, reason: update.reason ?? "Detail resync required")
                } else {
                    markLiveSessionStale(update.reason ?? "Detail resync required.")
                }
                return
            }
            let dataSnapshot = try await dataEngine.apply(
                update: update,
                expectedThreadID: row.threadID
            )
            applyDataSnapshot(dataSnapshot)
            requestCardPresentation.prune(to: dataSnapshot.events)
            liveState = update.liveState == "closed" ? .closed : .live
            DockLog.threadDetail.debug("thread detail update handled thread_id=\(DockLog.publicID(self.row.threadID), privacy: .public) live_state=\(self.liveState.logDescription, privacy: .public)")
            publishLoaded()
        } catch {
            liveState = .stale(message(from: error))
            DockLog.threadDetail.warning("thread detail update failed thread_id=\(DockLog.publicID(self.row.threadID), privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
            publishLoaded()
        }
    }

    private func markLiveSessionStale(_ message: String) {
        guard !isClosing, case .loaded = state else {
            return
        }
        switch liveState {
        case .closed, .stale:
            return
        case .connecting, .reconnecting, .live:
            break
        }
        liveState = .stale(message)
        DockLog.threadDetail.warning("thread detail marked stale thread_id=\(DockLog.publicID(self.row.threadID), privacy: .public) reason=\(DockLog.redacted(message), privacy: .public)")
        publishLoaded()
    }

    private func publishLoaded() {
        let signpostState = DockSignpost.rendering.beginInterval(RenderSignpostName.threadMainPublish)
        defer {
            DockSignpost.rendering.endInterval(RenderSignpostName.threadMainPublish, signpostState)
        }
        let snapshot = ThreadDetailSnapshot(
            header: header,
            liveState: liveState,
            events: events
        )
        state = .loaded(snapshot)
        screenStore.publish(snapshot: snapshot, requestCardPresentation: requestCardPresentation)
        publishConnectivity(liveState: liveState)
    }

    private func applyDataSnapshot(_ snapshot: ThreadDetailDataSnapshot) {
        events = snapshot.events
        activeTurnID = snapshot.activeTurnID
    }

    private func publishConnectivity(liveState: ThreadDetailLiveState) {
        guard let connectivityEventSink else {
            connectivityReporter?.reportThreadDetail(host: host, liveState: liveState)
            return
        }

        let event = ConnectivityRuntimeEvent(
            source: .threadDetail,
            hostID: host.id,
            route: "thread/detail",
            status: liveState.label,
            phase: connectivityPhase(for: liveState),
            recordedAt: now()
        )
        Task {
            await connectivityEventSink.record(event)
        }
    }

    private nonisolated func connectivityPhase(
        for liveState: ThreadDetailLiveState
    ) -> HostConnectivityPhase {
        switch liveState {
        case .connecting:
            return .checking
        case .reconnecting(let message):
            return .reconnecting(message)
        case .live:
            return .online("Live")
        case .stale(let message):
            return .stale(message)
        case .closed:
            return .offline("Closed")
        }
    }

    private func setCardStatus(cardID: String, status: ServerRequestCardStatus) {
        guard requestCardPresentation.setStatus(
            projectionID: cardID,
            status: status,
            in: events
        ) else {
            return
        }
        publishCurrentRenderState()
    }

    private func publishCurrentRenderState() {
        guard case .loaded(let snapshot) = state else {
            return
        }
        screenStore.publish(snapshot: snapshot, requestCardPresentation: requestCardPresentation)
    }

    private func message(from error: Error) -> String {
        if let message = ThreadDetailHumanOnlyRejection.message(for: error) {
            return message
        }
        if let localizedError = error as? LocalizedError,
           let description = localizedError.errorDescription {
            return description
        }
        return error.localizedDescription
    }

}

private extension AppServerConnectionState {
    var logDescription: String {
        switch self {
        case .idle:
            return "idle"
        case .connecting:
            return "connecting"
        case .connected:
