    if (closing) {
      return;
    }
    closing = true;
    serverHandle.logger?.info("relay.shutdown_signal");
    const forceExit = setTimeout(() => process.exit(0), RELAY_SHUTDOWN_PROCESS_TIMEOUT_MS);
    forceExit.unref();
    serverHandle.close()
